import React, { useState } from 'react';
import { Card, CardContent, Typography, Box, Divider, Button, TextField, CircularProgress, Snackbar, Alert, Dialog, DialogTitle, DialogContent, DialogActions, Switch, FormControlLabel } from '@mui/material';

const FrameDetailsPage = ({ frames, onBack }) => {
    const API_BASE = 'http://localhost:8000';
    // Mapping of common detected categories to richer YouTube-style policy explications.
    // Each entry provides: why it violates, severity indicators, contextual considerations,
    // required action, and suggested mitigations for creators/moderators.
    const POLICY_EXPLICATIONS = {
        suggestive_content: {
            title: 'Sexually suggestive content',
            why: 'Content that focuses sexual attention on a person or contains provocative behavior can be sexually suggestive and is restricted on YouTube.',
            severity: 'sexual focus, provocative dancing, sexual scenarios',
            context: 'Consider artistic intent, camera framing, clothing, and age-appropriateness; sexualized content of minors is strictly disallowed.',
            action_required: 'age_restriction',
            mitigation: 'Blur or crop sexualized regions; add an age restriction; replace or remove explicit segments; provide contextual information (educational/artistic justification) when appropriate.'
        },
        misinformation: {
            title: 'False or misleading information',
            why: 'Content that makes false claims or presents misleading facts can harm viewers and spread misinformation.',
            severity: 'health misinformation, election fraud claims, high-impact false claims',
            context: 'Differentiate satire/opinion from factual claims; check whether the content asserts verifiable facts or offers clearly labeled opinion.',
            action_required: 'fact_check_label',
            mitigation: 'Add fact-check labels or context boxes; provide reliable sources; remove demonstrably false claims; add disclaimers for satire.'
        },
        artistic_adult_content: {
            title: 'Artistic or educational adult content',
            why: 'Content containing nudity or sexual activity may be allowed in artistic, educational, or documentary contexts but often requires restrictions.',
            severity: 'sexual intent, focus on genitals, pornographic elements',
            context: 'Assess artistic merit, educational value, audience targeting and whether the depiction is gratuitous.',
            action_required: 'age_restriction',
            mitigation: 'Apply age restriction, add contextual framing in the title/description, or edit out explicit portions if not essential for the artistic/educational goal.'
        },
        dangerous_activity: {
            title: 'Content showing dangerous or harmful activities',
            why: 'Content that depicts or promotes life-threatening or easily copyable dangerous activities is restricted and may require removal or age gating.',
            severity: 'life-threatening, copyable dangers, no safety warnings',
            context: 'Differentiate professional demonstrations with safety protocols from amateur depictions without safeguards.',
            action_required: 'age_restriction_or_removal',
            mitigation: 'Add safety warnings, remove step-by-step instructions for dangerous acts, include professional disclaimers, or blur/remove the most hazardous segments.'
        }
    };

    // Backfilled mapping for categories that may have sparse DB hits — concise summaries taken from the policies dump
    Object.assign(POLICY_EXPLICATIONS, {
        violent_or_graphic_content: {
            title: 'Violent or graphic content',
            why: 'Violent or gory content intended to shock or disgust viewers, or content encouraging violence, is disallowed or restricted.',
            severity: 'graphic injury, encouragement of violence, glorification',
            context: 'Educational or newsworthy context may permit limited use with warnings; otherwise remove or age-restrict.',
            action_required: 'removal_or_age_restriction',
            mitigation: 'Blur graphic regions, add contextual narration, or remove the clip.'
        },
        hate_speech: {
            title: 'Hate speech',
            why: 'Content that dehumanizes or attacks protected groups is not allowed and should be removed or escalated.',
            severity: 'slurs, calls for violence, dehumanization',
            context: 'Assess whether content is quoted for reporting or is being endorsed; contextual reporting may be allowed for news/analysis.',
            action_required: 'removal_or_report',
            mitigation: 'Remove hateful language, add contextual disclaimers, or escalate for human review.'
        },
        child_safety: {
            title: 'Child safety',
            why: 'Content that endangers minors or sexualizes minors is strictly disallowed.',
            severity: 'involving minors in sexual or dangerous situations',
            context: 'Any sexualized depiction of minors or dangerous stunts involving minors requires removal and escalation.',
            action_required: 'removal_and_escalation',
            mitigation: 'Remove content and flag for human review; do not rely on automated mitigation alone.'
        },
        nudity_sexual_content: {
            title: 'Nudity & Sexual Content',
            why: 'Explicit sexual content intended for sexual gratification is disallowed or age-restricted.',
            severity: 'explicit nudity, sexual acts, fetishized content',
            context: 'Artistic or educational contexts may allow restricted presentation; sexualized minors are never allowed.',
            action_required: 'age_restriction_or_removal',
            mitigation: 'Blur or remove explicit regions; add age restrictions when appropriate.'
        },
        harassment_cyberbullying: {
            title: 'Harassment & cyberbullying',
            why: 'Repeated targeted insults, threats, or doxxing of individuals is disallowed.',
            severity: 'threats, doxxing, targeted sustained harassment',
            context: 'News or academic reporting may include quotes; repeated targeted abuse is disallowed.',
            action_required: 'removal_or_moderation',
            mitigation: 'Remove abusive commentary, blur identifying information, escalate as needed.'
        },
        misinformation: POLICY_EXPLICATIONS.misinformation || {
            title: 'Misinformation',
            why: 'False or misleading content that risks real-world harm is restricted.',
            severity: 'public safety, health, election impacts',
            context: 'Differ between opinion/satire and harmful factual claims.',
            action_required: 'fact_check_or_remove',
            mitigation: 'Add fact-check labels, provide reliable sources, or remove egregious claims.'
        },
        suicide_self_harm: {
            title: 'Suicide & self-harm',
            why: 'Content promoting or instructing self-harm is disallowed.',
            severity: 'instructions, glorification, targeted at minors',
            context: 'Educational or supportive content may be permitted with resources.',
            action_required: 'removal_and_support_resources',
            mitigation: 'Remove harmful instructions; provide helpline links and resources.'
        }
        ,
        spam_deceptive_practices: {
            title: 'Spam, deceptive practices & scams',
            why: 'Spam, scams, and deceptive practices that mislead users or direct them off-platform are disallowed.',
            severity: 'phishing, malware distribution, fraudulent schemes',
            context: 'Assess whether content is promotional spam or an isolated benign mention.',
            action_required: 'removal_or_report',
            mitigation: 'Remove deceptive links, add warnings, and escalate repeated offenders.'
        },
        safe_content: {
            title: 'Safe Content',
            why: 'Content that complies with policies and is appropriate for general audiences.',
            severity: 'low',
            context: 'Educational, news, or entertainment that follows community guidelines.',
            action_required: 'none',
            mitigation: 'No action required.'
        },
        educational_content: {
            title: 'Educational Content',
            why: 'Content intended to teach, inform, or explain topics in a clear and accurate way.',
            severity: 'low',
            context: 'Prefer accurate sourcing and clear framing for contested topics.',
            action_required: 'none',
            mitigation: 'Encourage citations and context.'
        },
        entertainment_content: {
            title: 'Entertainment Content',
            why: 'Content designed to amuse, engage, or entertain viewers in a safe manner.',
            severity: 'low',
            context: 'Check for age-appropriate markers for minors.',
            action_required: 'none',
            mitigation: 'No action required.'
        }
    });
    const [blurStrengths, setBlurStrengths] = useState({});
    const [processing, setProcessing] = useState({});
    const [previewUrls, setPreviewUrls] = useState({});
    const [toast, setToast] = useState({ open: false, severity: 'success', message: '' });
    const [selectedPolicy, setSelectedPolicy] = useState(null);
    // UI preference: whether to prefer DB policy text when available (persisted to localStorage)
    const [preferDb, setPreferDb] = useState(() => {
        try { const v = localStorage.getItem('preferDbPolicyText'); return v === null ? true : v === '1'; } catch (e) { return true; }
    });
    // Show ALL frames, not just non-compliant ones
    if (!frames || frames.length === 0) return <Typography>No frames found.</Typography>;
    const handleBack = () => {
        if (onBack) {
            onBack();
        }
    };
    return (
        <Box sx={{ p: 4 }}>
            <Button variant="outlined" color="primary" sx={{ mb: 2 }} onClick={handleBack}>
                ← Back
            </Button>
            <Typography variant="h4" color="primary" sx={{ mb: 3, fontWeight: 'bold' }}>
                Detailed Frame Report
            </Typography>
            <FormControlLabel control={<Switch checked={preferDb} onChange={(e) => { setPreferDb(e.target.checked); try { localStorage.setItem('preferDbPolicyText', e.target.checked ? '1' : '0'); } catch (e) {} }} />} label="Prefer DB policy text when available" sx={{ mb: 2 }} />
            {frames.map((frame, idx) => (
                <Card key={idx} sx={{ mb: 2, boxShadow: 2 }}>
                    <CardContent>
                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>Frame {frame.frame_index !== undefined ? frame.frame_index + 1 : idx + 1}</Typography>
                        <Typography variant="body2">Timestamp: <b>{frame.timestamp !== undefined ? frame.timestamp : 'N/A'}</b></Typography>
                        {frame.preview_path && <img src={frame.preview_path} alt={`Frame ${idx + 1}`} style={{ maxWidth: 320, borderRadius: 8, marginBottom: 8 }} />}
                        <Divider sx={{ my: 1 }} />
                        {/* Derive an override: consider DB evidence, explicit action_required, or severity indicators => treat as violation.
                            Exclude DB hits that are explicit 'safe' labels unless they include an actionable field (action_required/severity). */}
                        {(() => {
                            const hasDbEvidence = Array.isArray(frame.retrieved_policies) && frame.retrieved_policies.length > 0;
                            // treat DB evidence as relevant only when it indicates action or non-low severity,
                            // or when its category is not an explicit "safe" label.
                            const dbEvidenceRelevant = hasDbEvidence && frame.retrieved_policies.some(p => {
                                const cat = String(p.policy_info?.category || p.category || '').toLowerCase().replace(/\s+/g, '_');
                                const action = p.policy_info?.action_required || p.action_required || p.action;
                                const severity = p.policy_info?.severity || p.severity || p.importance;
                                if (action && String(action).toLowerCase() !== 'none') return true;
                                if (severity && String(severity).toLowerCase() !== 'low') return true;
                                // if category is explicitly 'safe' or 'safe_content' then ignore unless action/severity above triggered
                                if (cat === 'safe' || cat === 'safe_content') return false;
                                // otherwise treat as relevant
                                return cat !== '';
                            });
                            const hasAction = Boolean(frame.action_required || (frame.policy && frame.policy.action_required));
                            const hasSeverity = Boolean((frame.severity_indicators && frame.severity_indicators.length > 0) || (frame.policy && (frame.policy.severity || (frame.policy.severity_indicators && frame.policy.severity_indicators.length > 0))));
                            // set a non-enumerable flag on the frame for downstream rendering
                            try { frame.__isViolation = dbEvidenceRelevant || hasAction || hasSeverity || Boolean(frame.combined_violation) || Boolean(frame.visual_analysis?.violation_detected); } catch (e) { /* ignore immutables */ }
                            return null;
                        })()}
                        <Typography variant="body2">Category: <b>{frame.__isViolation ? 'BAD CONTENT' : (frame.visual_analysis?.category || frame.category || 'N/A')}</b></Typography>
                        <Typography variant="body2">Confidence: <b>{frame.visual_analysis?.confidence !== undefined ? frame.visual_analysis.confidence : frame.confidence || 'N/A'}</b></Typography>
                        <Typography variant="body2">Violation Detected: <b>{frame.__isViolation ? 'Yes' : (frame.visual_analysis?.violation_detected !== undefined ? (frame.visual_analysis.violation_detected ? 'Yes' : 'No') : (frame.combined_violation ? 'Yes' : 'No'))}</b></Typography>
                        <Divider sx={{ my: 1 }} />
                        {frame.blip_description?.description && frame.blip_description.description.trim() !== '' ? (
                            <Typography variant="body2">BLIP Description: <b>{frame.blip_description.description}</b></Typography>
                        ) : (
                            <Typography variant="body2">BLIP Description: <b>N/A</b></Typography>
                        )}
                        {/* Show raw model BLIP text if present (separate from blip_description object) */}
                        {frame.blip && String(frame.blip).trim() !== '' && (
                            <Typography variant="body2">Model BLIP: <b>{frame.blip}</b></Typography>
                        )}
                        {/* Show BLIP text returned as part of RAG evidence if available */}
                        {frame.rag_decision?.explanation?.evidence?.visual_result?.blip && (
                            <Typography variant="body2">RAG BLIP: <b>{frame.rag_decision.explanation.evidence.visual_result.blip}</b></Typography>
                        )}
                        {frame.ocr_text?.text && frame.ocr_text.text.trim() !== '' ? (
                            <Typography variant="body2">OCR Text: <b>{frame.ocr_text.text}</b></Typography>
                        ) : (
                            <Typography variant="body2">OCR Text: <b>N/A</b></Typography>
                        )}
                        {/* Show raw model OCR if present (separate field) */}
                        {frame.ocr && String(frame.ocr).trim() !== '' && (
                            <Typography variant="body2">Model OCR: <b>{frame.ocr}</b></Typography>
                        )}
                        {/* Show OCR text returned as part of RAG evidence if available */}
                        {frame.rag_decision?.explanation?.evidence?.visual_result?.ocr && (
                            <Typography variant="body2">RAG OCR: <b>{frame.rag_decision.explanation.evidence.visual_result.ocr}</b></Typography>
                        )}
                        {frame.ocr_text?.extracted_items && frame.ocr_text.extracted_items.length > 0 && (
                            <Typography variant="body2">OCR Items: <b>{frame.ocr_text.extracted_items.map((item, i) => item.text).join(', ')}</b></Typography>
                        )}
                        {/* DB evidence bullets */}
                        {frame.retrieved_policies && frame.retrieved_policies.length > 0 && (
                            <Box component="ul" sx={{ pl: 2, mt: 1 }}>
                                {frame.retrieved_policies.map((p, i) => (
                                    <Box component="li" key={i} sx={{ cursor: 'pointer', mb: 0.8 }} onClick={() => setSelectedPolicy(p)}>
                                        <Typography variant="body2"><strong>{p.policy_info?.category || p.category || 'policy'}</strong> — {p.policy_info?.title || p.policy_info?.policy_text || p.policy_info?.description || p.description || 'No description'}</Typography>
                                        <Typography variant="caption" color="text.secondary">Source: {p.source || p.policy_info?.source || 'database'} | sim: {p.similarity !== undefined ? Number(p.similarity).toFixed(3) : 'N/A'}</Typography>
                                    </Box>
                                ))}
                            </Box>
                        )}
                        {/* RAG explanation: structured, DB-backed explanation provided by backend */}
                        {frame.rag_decision && frame.rag_decision.explanation && (
                            <Box sx={{ mt: 1, p: 1, borderRadius: 1, background: '#fbfbff', border: '1px solid rgba(0,0,0,0.06)' }}>
                                <Typography variant="subtitle2">RAG Explanation</Typography>
                                {frame.rag_decision.explanation.verdict_summary && (
                                    <Typography variant="body2" sx={{ mt: 0.5 }}><strong>{frame.rag_decision.explanation.verdict_summary}</strong></Typography>
                                )}

                                {frame.rag_decision.explanation.primary_policy && (
                                    <Box sx={{ mt: 1 }}>
                                        <Typography variant="body2"><strong>Primary policy:</strong> {frame.rag_decision.explanation.primary_policy.category} <small>({Number(frame.rag_decision.explanation.primary_policy.similarity || 0).toFixed(3)})</small></Typography>
                                        {frame.rag_decision.explanation.primary_policy.policy_text_snippet && (
                                            <Typography variant="body2" sx={{ mt: 0.5 }}>{frame.rag_decision.explanation.primary_policy.policy_text_snippet}</Typography>
                                        )}
                                        {frame.rag_decision.explanation.primary_policy.examples && frame.rag_decision.explanation.primary_policy.examples.length > 0 && (
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Examples:</strong> {frame.rag_decision.explanation.primary_policy.examples.join(', ')}</Typography>
                                        )}
                                    </Box>
                                )}

                                {frame.rag_decision.explanation.matched_policies && frame.rag_decision.explanation.matched_policies.length > 0 && (
                                    <Box sx={{ mt: 1 }}>
                                        <Typography variant="body2"><strong>Other matched policies:</strong></Typography>
                                        {frame.rag_decision.explanation.matched_policies.map((mp, i) => (
                                            <Typography key={i} variant="caption" color="text.secondary" display="block">• {mp.category} (sim {Number(mp.similarity || 0).toFixed(3)})</Typography>
                                        ))}
                                    </Box>
                                )}

                                <Box sx={{ mt: 1 }}>
                                    <Typography variant="body2"><strong>Evidence:</strong> {frame.rag_decision.explanation.evidence?.visual_result?.blip || frame.blip || frame.blip_description?.description || frame.ocr || frame.ocr_text?.text || 'N/A'}</Typography>
                                    <Typography variant="body2"><strong>Model confidence:</strong> {frame.rag_decision.explanation.evidence?.visual_result?.confidence ?? frame.visual_analysis?.confidence ?? 'N/A'}</Typography>
                                </Box>

                                <Box sx={{ mt: 1 }}>
                                    <Typography variant="body2"><strong>Recommended action:</strong> {frame.rag_decision.explanation.recommended_action?.action || frame.action_required || 'review'}</Typography>
                                    {frame.rag_decision.explanation.recommended_action?.rationale && (
                                        <Typography variant="body2" sx={{ mt: 0.5, fontStyle: 'italic' }}>{frame.rag_decision.explanation.recommended_action.rationale}</Typography>
                                    )}
                                </Box>
                            </Box>
                        )}
                        {/* Policy, Examples, Action Required from RAG if available */}
                        {frame.policy && frame.policy.description && (
                            <Typography variant="body2">Policy: <b>{frame.policy.description}</b></Typography>
                        )}
                        {/* Removed personalized reason rendering to avoid exposing noisy/ambiguous per-frame heuristics */}
                        {frame.examples && frame.examples.length > 0 && (
                            <Typography variant="body2">Examples: <b>{frame.examples.join(', ')}</b></Typography>
                        )}
                        {frame.action_required && (
                            <Typography variant="body2">Action Required: <b>{frame.action_required}</b></Typography>
                        )}
                        {frame.severity_indicators && frame.severity_indicators.length > 0 && (
                            <Typography variant="body2">Severity indicators: <b>{frame.severity_indicators.join(', ')}</b></Typography>
                        )}
                        {frame.context_factors && frame.context_factors.length > 0 && (
                            <Typography variant="body2">Context factors: <b>{frame.context_factors.join(', ')}</b></Typography>
                        )}
                        <Divider sx={{ my: 1 }} />
                        <Typography variant="body2">Preview Path: <b>{frame.preview_path || 'N/A'}</b></Typography>
                        <Typography variant="body2">Frame Index: <b>{frame.frame_index !== undefined ? frame.frame_index : idx}</b></Typography>
                        {/* Clear policy/action bullets */}
                        {frame.policy && (
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="subtitle2">Policy summary</Typography>
                                <Box component="ul" sx={{ pl: 2, mt: 0.5 }}>
                                    <li><Typography variant="body2">{frame.policy.description || frame.policy.summary || 'No policy text available'}</Typography></li>
                                    {frame.policy.action_required && <li><Typography variant="body2"><strong>Action required:</strong> {frame.policy.action_required}</Typography></li>}
                                    {frame.policy.severity && <li><Typography variant="body2"><strong>Severity:</strong> {frame.policy.severity}</Typography></li>}
                                </Box>
                            </Box>
                        )}
                        {/* Enhanced YouTube-style policy explication derived from detected categories or DB evidence */}
                        <Box sx={{ mt: 1 }}>
                            <Typography variant="subtitle2">YouTube policy explication</Typography>
                            <Box sx={{ mt: 0.5 }}>
                                {(() => {
                                    // pick best key: explicit category, retrieved_policies first item's category hint, or heuristics
                                    const keyCandidates = [];
                                    if (frame.category) keyCandidates.push(String(frame.category).toLowerCase().replace(/\s+/g, '_'));
                                    if (frame.visual_analysis && frame.visual_analysis.tag) keyCandidates.push(String(frame.visual_analysis.tag).toLowerCase());
                                    if (Array.isArray(frame.retrieved_policies) && frame.retrieved_policies.length > 0) {
                                        const fp = frame.retrieved_policies[0];
                                        if (fp.policy_info && fp.policy_info.category) keyCandidates.push(String(fp.policy_info.category).toLowerCase().replace(/\s+/g, '_'));
                                        if (fp.category) keyCandidates.push(String(fp.category).toLowerCase().replace(/\s+/g, '_'));
                                    }
                                    // Map a few known synonyms
                                    const normalize = (k) => {
                                        if (!k) return k;
                                        if (/suggestive|sexual|adult/.test(k)) return 'suggestive_content';
                                        if (/misinfo|misinformation|false|misleading/.test(k)) return 'misinformation';
                                        if (/artistic_adult|artistic|adult/.test(k)) return 'artistic_adult_content';
                                        if (/danger|harm|unsafe|dangerous/.test(k)) return 'dangerous_activity';
                                        return k.replace(/[^a-z0-9_]/g, '_');
                                    };
                                    let chosen = null;
                                    // If DB evidence exists and user prefers DB text, prefer its canonical policy text for explication
                                    if (preferDb && Array.isArray(frame.retrieved_policies) && frame.retrieved_policies.length > 0) {
                                        const fp = frame.retrieved_policies[0];
                                        const info = fp.policy_info || fp;
                                        if (info) {
                                            // Try to parse examples if stored as JSON string or comma-separated string
                                            let examples = info.examples;
                                            try {
                                                if (typeof examples === 'string') {
                                                    // try JSON first
                                                    try {
                                                        const parsed = JSON.parse(examples);
                                                        if (Array.isArray(parsed)) examples = parsed;
                                                    } catch (je) {
                                                        // fallback: comma-split
                                                        examples = examples.split(/\s*,\s*/).filter(Boolean);
                                                    }
                                                }
                                            } catch (e) {
                                                // leave as-is
                                            }
                                            const normalizedTitle = (info.title || info.policy_text || info.category || fp.category || frame.category || 'Policy');
                                            chosen = {
                                                title: String(normalizedTitle).trim(),
                                                why: info.description || info.policy_text || fp.description || 'Policy text not available.',
                                                severity: info.severity || info.importance || (frame.policy && frame.policy.severity) || 'Not specified',
                                                context: info.context || (frame.context_factors && frame.context_factors.join(', ')) || 'Context not provided',
                                                action_required: info.action_required || info.action || frame.action_required || fp.action_required || 'Review required',
                                                mitigation: info.mitigation || 'Refer to policy text and examples; consider editing, age-restricting, or removing the content depending on severity and context.',
                                                examples: Array.isArray(examples) ? examples : (examples ? [examples] : []),
                                                source: info.source || fp.source || 'database'
                                            };
                                        }
                                    }
                                    // fallback: check static mapping by normalized keys
                                        if (!chosen) {
                                        for (const kc of keyCandidates) {
                                            const n = normalize(kc);
                                            if (n && POLICY_EXPLICATIONS[n]) { chosen = POLICY_EXPLICATIONS[n]; break; }
                                        }
                                    }
                                    // fallback: display synthesized info from fields when no mapping available
                                        if (!chosen) {
                                        // attempt to synthesize from frame fields (do not use personalized_reason to avoid noisy labels)
                                        const synthWhyParts = [];
                                        if (frame.policy && frame.policy.description) synthWhyParts.push(frame.policy.description);
                                        if (frame.blip_description && frame.blip_description.description) synthWhyParts.push(`Visual: ${frame.blip_description.description}`);
                                        const synth = {
                                            title: frame.category || frame.visual_analysis?.category || 'Detected issue',
                                            why: synthWhyParts.join(' — ') || 'The model flagged this frame for potential policy concerns.',
                                            severity: (frame.severity_indicators && frame.severity_indicators.join(', ')) || (frame.policy && frame.policy.severity) || 'Not specified',
                                            context: (frame.context_factors && frame.context_factors.join(', ')) || 'Context not provided',
                                            action_required: frame.action_required || (frame.policy && frame.policy.action_required) || 'Review required',
                                            mitigation: 'Consider editing, age-restricting, or removing the content depending on severity and context.'
                                        };
                                        chosen = synth;
                                    }
                                    return (
                                        <Box sx={{ background: '#fff', borderRadius: 1, p: 1, border: '1px solid rgba(0,0,0,0.06)' }}>
                                            <Typography variant="body2"><strong>{chosen.title}</strong></Typography>
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Why this is a concern:</strong> {chosen.why}</Typography>
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Severity:</strong> {chosen.severity}</Typography>
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Context considerations:</strong> {chosen.context}</Typography>
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Action required:</strong> {chosen.action_required}</Typography>
                                            <Typography variant="body2" sx={{ mt: 0.5 }}><strong>Suggested mitigation:</strong> {chosen.mitigation}</Typography>
                                        </Box>
                                    );
                                })()}
                            </Box>
                        </Box>
                        {/* Blur controls and preview */}
                        <Box sx={{ mt: 1, display: 'flex', gap: 1, alignItems: 'center' }}>
                            <TextField size="small" label="Blur px" type="number" value={blurStrengths[idx] ?? 10} onChange={(e) => setBlurStrengths(s => ({ ...s, [idx]: Number(e.target.value) }))} sx={{ width: 120 }} />
                            {processing[idx] ? (
                                <CircularProgress size={20} />
                            ) : (
                                <Button size="small" variant="contained" onClick={async () => {
                                    const strength = Number(blurStrengths[idx] ?? 10) || 10;
                                    setProcessing(p => ({ ...p, [idx]: true }));
                                    try {
                                        // Try to use video id if present on frame
                                        const vid = frame.video_id || frame.videoId || frame.video || null;
                                            // const payload = {
                                            //     type: 'frame_fix',
                                            //     frame: frame.frame_index !== undefined ? frame.frame_index : frame.frame,
                                            //     timestamp: frame.timestamp || null,
                                            //     action: 'blur',
                                            //     options: { strength },
                                            //     source_path: frame.source_path || frame.preview_path || null
                                            // };
                                            // let resp = null;
                                        let effectiveVid = vid;
                                        // If no video id, first save a minimal report to obtain one
                                        if (!effectiveVid) {
                                            try {
                                                const savePayload = {
                                                    filename: frame.video_title || frame.filename || `frame_preview_${idx}`,
                                                    video_title: frame.video_title || frame.filename || `frame_preview_${idx}`,
                                                    frame_preview: {
                                                        frame_index: frame.frame_index,
                                                        timestamp: frame.timestamp,
                                                        preview_path: frame.preview_path || null,
                                                        category: frame.visual_analysis?.category || frame.category || null
                                                    }
                                                };
                                                const saveResp = await fetch(`${API_BASE}/api/videos/save-or-id`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(savePayload) });
                                                if (saveResp.ok) {
                                                    const sdata = await saveResp.json().catch(() => null);
                                                    if (sdata && sdata.video_id) {
                                                        effectiveVid = sdata.video_id;
                                                    }
                                                }
                                            } catch (e) {
                                                // ignore save failure and proceed to attempt apply (it will fail if backend requires id)
                                                // eslint-disable-next-line no-console
                                                console.warn('save-or-id failed', e);
                                            }
                                        }

                                        // Prefer the single-frame synchronous blur endpoint to get immediate proof
                                        if (effectiveVid) {
                                            try {
                                                const blurPayload = {
                                                    preview_path: frame.preview_path || frame.source_path || null,
                                                    options: { strength }
                                                };
                                                const blurResp = await fetch(`${API_BASE}/api/videos/${effectiveVid}/apply-frame-blur`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(blurPayload) });
                                                if (!blurResp.ok) {
                                                    const txt = await blurResp.text().catch(() => '');
                                                    // eslint-disable-next-line no-alert
                                                    alert('Blur failed: ' + (txt || blurResp.statusText || blurResp.status));
                                                } else {
                                                    const bdata = await blurResp.json().catch(() => null);
                                                    if (bdata && bdata.result_path) {
                                                        setPreviewUrls(p => ({ ...p, [idx]: bdata.result_path }));
                                                        setToast({ open: true, severity: 'success', message: 'Frame blurred — preview ready' });
                                                    } else {
                                                        setToast({ open: true, severity: 'warning', message: 'Blur completed but no preview returned' });
                                                    }
                                                }
                                            } catch (e) {
                                                // eslint-disable-next-line no-console
                                                console.error('Frame blur request failed', e);
                                                setToast({ open: true, severity: 'error', message: 'Frame blur request failed' });
                                            }
                                        } else {
                                            // No video id available; inform user to save or use the main apply flow
                                            setToast({ open: true, severity: 'error', message: 'No video id available — save the report first' });
                                        }
                                    } catch (err) {
                                        // eslint-disable-next-line no-console
                                        console.error('Apply blur failed', err);
                                        // eslint-disable-next-line no-alert
                                        alert('Apply blur failed: ' + (err.message || err));
                                    }
                                    setProcessing(p => ({ ...p, [idx]: false }));
                                }}>Apply Blur & Preview</Button>
                            )}
                        </Box>
                        {previewUrls[idx] && (
                            <Box sx={{ mt: 1 }}>
                                <Typography variant="body2">Preview:</Typography>
                                {/\.(jpe?g|png|webp|gif)$/i.test(previewUrls[idx]) ? (
                                    <img src={previewUrls[idx]} alt={`Preview ${idx}`} style={{ maxWidth: 480, borderRadius: 8, marginTop: 8 }} />
                                ) : (
                                    <video src={previewUrls[idx]} controls style={{ maxWidth: 480, borderRadius: 8, marginTop: 8 }} />
                                )}
                            </Box>
                        )}
                        <Snackbar open={toast.open} autoHideDuration={4000} onClose={() => setToast(t => ({ ...t, open: false }))}>
                            <Alert onClose={() => setToast(t => ({ ...t, open: false }))} severity={toast.severity} sx={{ width: '100%' }}>
                                {toast.message}
                            </Alert>
                        </Snackbar>
                        <Dialog open={Boolean(selectedPolicy)} onClose={() => setSelectedPolicy(null)} maxWidth="sm" fullWidth>
                            <DialogTitle>{selectedPolicy?.policy_info?.title || selectedPolicy?.category || String(selectedPolicy?.policy_info?.description || '').slice(0,60) || 'Policy detail'}</DialogTitle>
                            <DialogContent dividers>
                                <Typography variant="subtitle2" sx={{ mb: 1 }}>{selectedPolicy?.policy_info?.category || selectedPolicy?.category}</Typography>
                                <Typography variant="caption" color="text.secondary">Source: {selectedPolicy?.source || selectedPolicy?.policy_info?.source || 'database'}{selectedPolicy?.similarity ? ` • similarity: ${Number(selectedPolicy.similarity).toFixed(3)}` : ''}</Typography>
                                <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', mt: 1 }}>{selectedPolicy?.policy_info?.policy_text || selectedPolicy?.policy_info?.description || selectedPolicy?.description || 'No description available.'}</Typography>
                                {/** show examples, severity, action_required, source when available **/}
                                {selectedPolicy?.policy_info?.examples && (
                                    <Box sx={{ mt: 1 }}>
                                        <Typography variant="subtitle2">Examples</Typography>
                                        {(() => {
                                            let ex = selectedPolicy.policy_info.examples;
                                            try {
                                                if (typeof ex === 'string') {
                                                    const parsed = JSON.parse(ex);
                                                    if (Array.isArray(parsed)) ex = parsed;
                                                }
                                            } catch (e) {
                                                // fallback to comma-split if not valid JSON
                                                if (typeof ex === 'string') ex = ex.split(/\s*,\s*/).filter(Boolean);
                                            }
                                            if (Array.isArray(ex)) {
                                                return ex.map((ee, i) => <Typography key={i} variant="body2">• {ee}</Typography>);
                                            }
                                            return <Typography variant="body2">{String(ex)}</Typography>;
                                        })()}
                                    </Box>
                                )}
                                {(selectedPolicy?.policy_info?.severity || selectedPolicy?.severity) && <Typography variant="body2" sx={{ mt: 1 }}><strong>Severity:</strong> {selectedPolicy?.policy_info?.severity || selectedPolicy?.severity}</Typography>}
                                {(selectedPolicy?.policy_info?.action_required || selectedPolicy?.action_required) && <Typography variant="body2" sx={{ mt: 1 }}><strong>Action required:</strong> {selectedPolicy?.policy_info?.action_required || selectedPolicy?.action_required}</Typography>}
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>Source: {selectedPolicy?.policy_info?.source || selectedPolicy?.source || 'database'}</Typography>
                            </DialogContent>
                            <DialogActions>
                                <Button onClick={() => setSelectedPolicy(null)}>Close</Button>
                            </DialogActions>
                        </Dialog>
                        {/* Add more fields as needed for full model analysis */}
                    </CardContent>
                </Card>
            ))}
        </Box>
    );
};

export default FrameDetailsPage;
